        if nbytes == 1:
            return (self.regs[addr] & 0xFF00) >> 8
        else:
            return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data

        if addr == 0x3 and (data & 0x80) != 0:  # IO_LOCK
            for reg in self.regs:
                if reg != 0xF and reg != addr:
                    self.regs[reg] = 0

        if addr == 0xF and (data & 0x5AC) == 0x5AC:  # SW_RESET
            self.regs = {
                0x1: 0x0000,
                0x2: 0x0000,
                0x3: 0x0000,
                0x4: 0x0000,
                0x5: 0x0000,
                0x6: 0x00FF,
                0xF: 0x0000
            }

